static int find(int row, int value) {
    if (row < 0 || row >= ROW_N) return -1;
    for (int i = 0; i < CH_SPAN[row][1]; i++)
        if (CH_E[CH_SPAN[row][0] + i].value == value) return CH_SPAN[row][0] + i;
    return -1;
}

const char *ch_name(int row, int value) { int i = find(row, value); return i < 0 ? 0 : CH_STR + CH_E[i].name; }
int ch_count(int row) { return row < 0 || row >= ROW_N ? 0 : CH_SPAN[row][1]; }
int ch_value(int row, int index) { return CH_E[CH_SPAN[row][0] + index].value; }
int ch_flags(int row, int value) { int i = find(row, value); return i < 0 ? -1 : CH_E[i].flags; }
int ch_is_retired(int row, int value) { int f = ch_flags(row, value); return f >= 0 && CH_STATUS(f) >= 2; }

int ch_fits(int row, int value, int keys_ins) {
    if (row != ROW_COMP || keys_ins < 0 || keys_ins >= 32) return 1;
    int i = find(row, value);
    if (i < 0) return 1;
    i -= CH_SPAN[row][0];
    return ((CH_COMP_FIT[i][0] >> keys_ins) & 1u) && !((CH_COMP_FIT[i][1] >> keys_ins) & 1u);
}

int ch_rhythm_row(int keys_ins, int comp) {
    const int comp_row = ROW_COMP, strum = 5;
    if (!ch_fits(comp_row, strum, keys_ins)) return ROW_COMP;
    if (comp >= 0 && find(comp_row, comp) >= 0 && comp != strum && !ch_fits(comp_row, comp, keys_ins))
        return ROW_COMP;
    return ROW_STRUM_PAT;
}
